-- Stage English, Grade 8. Inactive until final activation; legacy rows remain available.
DO $stage_one_catalog$
DECLARE
  v_catalog jsonb := $payload${"subject":"English","grade":8,"strand_count":15,"sub_strand_count":75,"source_name":"KICD Junior School Curriculum Design - English Grade 8 (Rationalized 2024)","source_url":"https://drive.google.com/file/d/1WmQXD4FTiFrInrCQMu1w-cjmPPaLEvw5/preview","source_note":"Official KICD Grade 8 index: https://kicd.ac.ke/cbc-materials/curriculum-designs/grade-eight-designs/ Current public viewer: https://drive.google.com/file/d/1WmQXD4FTiFrInrCQMu1w-cjmPPaLEvw5/preview. Numbered two-level hierarchy transcribed from the grade summary; no topics tier. Report: research/verified-20260929/04-english.md","strands":[{"strand_name":"THEME 1: HUMAN RIGHTS","order":1,"sub_strands":[{"sub_strand_name":"1.1.1 Polite Language (telephone etiquette)","order":1},{"sub_strand_name":"1.2.1 Independent reading","order":2},{"sub_strand_name":"1.3.1 Word classes –compound Nouns","order":3},{"sub_strand_name":"1.4.1 Intensive reading – class reader – sequencing events","order":4},{"sub_strand_name":"1.5.1 Handwriting –Legibility","order":5}]},{"strand_name":"THEME 2: SCIENTIFIC INNOVATIONS","order":2,"sub_strands":[{"sub_strand_name":"2.1.1 Oral presentations – songs","order":1},{"sub_strand_name":"2.2.1 Simple poems","order":2},{"sub_strand_name":"2.3.1 Word classes – collective Nouns","order":3},{"sub_strand_name":"2.4.1 Class reader – setting (time and place)","order":4},{"sub_strand_name":"2.5.1 Punctuation marks","order":5}]},{"strand_name":"THEME 3: POLLUTION","order":3,"sub_strands":[{"sub_strand_name":"3.1.1 Listening comprehension","order":1},{"sub_strand_name":"3.2.1 Intensive reading – given texts","order":2},{"sub_strand_name":"3.3.1 Primary auxiliaries","order":3},{"sub_strand_name":"3.4.1 Intensive reading – poetry","order":4},{"sub_strand_name":"3.5.1 Narrative paragraphs","order":5}]},{"strand_name":"THEME 4: CONSUMER ROLES AND RESPONSIBILITES","order":4,"sub_strands":[{"sub_strand_name":"4.1.1 Selective listening","order":1},{"sub_strand_name":"4.2.1 Intensive reading – reading strategies","order":2},{"sub_strand_name":"4.3.1 Verbs and tenses","order":3},{"sub_strand_name":"4.4.1 Class reader – characters","order":4},{"sub_strand_name":"4.5.1 Paragraphing using examples","order":5}]},{"strand_name":"THEME 5: RELATIONSHIPS: PEERS","order":5,"sub_strands":[{"sub_strand_name":"5.1.1 Pronunciation","order":1},{"sub_strand_name":"5.2.1 Study skills-Reference materials","order":2},{"sub_strand_name":"5.3.1 Adjectives","order":3},{"sub_strand_name":"5.4.1 Class reader – style (dialogue and repetition)","order":4},{"sub_strand_name":"5.5.1 Friendly letter","order":5}]},{"strand_name":"THEME 6: REHABILITATION","order":6,"sub_strands":[{"sub_strand_name":"6.1.1 Conversational skills – disagreeing politely","order":1},{"sub_strand_name":"6.2.1 Reading fluency – poem","order":2},{"sub_strand_name":"6.3.1 Adverbs","order":3},{"sub_strand_name":"6.4.1 Class reader – main idea","order":4},{"sub_strand_name":"6.5.1 Commonly misspelt words","order":5}]},{"strand_name":"THEME 7: NATURAL RESOURCES: WILDLIFE","order":7,"sub_strands":[{"sub_strand_name":"7.1.1 Listening for details-responding appropriately","order":1},{"sub_strand_name":"7.2.1 Intensive reading – visuals","order":2},{"sub_strand_name":"7.3.1 Pronouns","order":3},{"sub_strand_name":"7.4.1 Class Reader – relationship between characters","order":4},{"sub_strand_name":"7.5.1 The writing process – narrative composition","order":5}]},{"strand_name":"THEME 8: TOURISM: DOMESTIC","order":8,"sub_strands":[{"sub_strand_name":"8.1.1 Oral Narratives – myths","order":1},{"sub_strand_name":"8.2.1 Intensive reading – poem","order":2},{"sub_strand_name":"8.3.1 Simple prepositions","order":3},{"sub_strand_name":"8.4.1 Intensive reading – poetry","order":4},{"sub_strand_name":"8.5.1 Composition – self assessment","order":5}]},{"strand_name":"THEME 9: HEROES AND HEROINES: AFRICA","order":9,"sub_strands":[{"sub_strand_name":"9.1.1 Pronunciation – sounds and stress","order":1},{"sub_strand_name":"9.2.1 Extensive reading – fiction -Characters","order":2},{"sub_strand_name":"9.3.1 Conjunctions","order":3},{"sub_strand_name":"9.4.1 Intensive reading-Similes and Metaphors","order":4},{"sub_strand_name":"9.5.1 Narrative Composition","order":5}]},{"strand_name":"THEME 10: ART","order":10,"sub_strands":[{"sub_strand_name":"10.1.1 Oral Presentations","order":1},{"sub_strand_name":"10.2.1 Study skills – note making","order":2},{"sub_strand_name":"10.3.1 Determiners and Quantifiers","order":3},{"sub_strand_name":"10.4.1 Class reader – relating events to real life","order":4},{"sub_strand_name":"10.5.1 Packing and Shopping lists","order":5}]},{"strand_name":"THEME 11: CHOOSING A CAREER","order":11,"sub_strands":[{"sub_strand_name":"11.1.1 Interviews","order":1},{"sub_strand_name":"11.2.1 Extensive Reading – non-fiction materials","order":2},{"sub_strand_name":"11.3.1 Adverbs","order":3},{"sub_strand_name":"11.4.1 Class reader – lessons learnt","order":4},{"sub_strand_name":"11.5.1 Spelling Antonyms ,Synonyms and Numbers","order":5}]},{"strand_name":"THEME 12: MODERN FASHION","order":12,"sub_strands":[{"sub_strand_name":"12.1.1 Listening to respond – attitude","order":1},{"sub_strand_name":"12.2.1 Reading comprehension","order":2},{"sub_strand_name":"12.3.1 Adverbs","order":3},{"sub_strand_name":"12.4.1 Class reader – writing about characters","order":4},{"sub_strand_name":"12.5.1 Writing process – dialogues","order":5}]},{"strand_name":"THEME 13: CONSUMER PROTECTION","order":13,"sub_strands":[{"sub_strand_name":"13.1.1 Extensive Listening – poems","order":1},{"sub_strand_name":"13.2.1 Intensive Reading – comprehension strategies","order":2},{"sub_strand_name":"13.3.1 Compound Sentences","order":3},{"sub_strand_name":"13.4.1 Class reader – style (personification, flashback)","order":4},{"sub_strand_name":"13.5.1 Narrative Composition","order":5}]},{"strand_name":"THEME 14: SPORTS: OLYMPICS","order":14,"sub_strands":[{"sub_strand_name":"14.1.1 Pronunciation and Intonation – silent consonant sounds","order":1},{"sub_strand_name":"14.2.1 Study skills – summary and note making","order":2},{"sub_strand_name":"14.3.1 Active and Passive voice","order":3},{"sub_strand_name":"14.4.1 Class reader – relating ideas to real life","order":4},{"sub_strand_name":"14.5.1 Descriptive writing","order":5}]},{"strand_name":"THEME 15: TOURIST ATTRACTION SITES: AFRICA","order":15,"sub_strands":[{"sub_strand_name":"15.1.1 Oral reports – events","order":1},{"sub_strand_name":"15.2.1 Reading Fluency","order":2},{"sub_strand_name":"15.3.1 Interrogative Sentences","order":3},{"sub_strand_name":"15.4.1 Poems","order":4},{"sub_strand_name":"15.5.1 Functional Writing – notices, posters","order":5}]}]}$payload$::jsonb;
  v_grade_id uuid;
  v_subject_id uuid;
  v_source_id uuid;
  v_strand_id uuid;
  v_strand jsonb;
  v_sub_strand jsonb;
  v_strands integer := 0;
  v_sub_strands integer := 0;
BEGIN
  IF EXISTS (SELECT 1 FROM public.curriculum_sources WHERE source_name = v_catalog->>'source_name' LIMIT 1) THEN
    RAISE EXCEPTION 'Source already staged: %', v_catalog->>'source_name';
  END IF;
  SELECT id INTO v_grade_id FROM public.curriculum_grades
    WHERE grade_number = (v_catalog->>'grade')::integer AND curriculum_type = 'CBE' LIMIT 1;
  IF v_grade_id IS NULL THEN RAISE EXCEPTION 'CBE Grade % missing.', v_catalog->>'grade'; END IF;
  SELECT id INTO v_subject_id FROM public.curriculum_subjects
    WHERE grade_id = v_grade_id AND subject_name = v_catalog->>'subject' LIMIT 1;
  IF v_subject_id IS NULL THEN RAISE EXCEPTION 'CBE Grade % subject missing: %.', v_catalog->>'grade', v_catalog->>'subject'; END IF;

  INSERT INTO public.curriculum_sources (source_name, source_url, source_type, license_status, retrieval_status, notes)
  VALUES (v_catalog->>'source_name', v_catalog->>'source_url', 'official_design', 'official_public', 'approved', v_catalog->>'source_note')
  RETURNING id INTO v_source_id;
  UPDATE public.curriculum_subjects SET curriculum_source_id = v_source_id WHERE id = v_subject_id;

  FOR v_strand IN SELECT value FROM jsonb_array_elements(v_catalog->'strands') LOOP
    INSERT INTO public.curriculum_strands (subject_id, strand_name, strand_description, strand_order, is_current)
    VALUES (v_subject_id, v_strand->>'strand_name', 'Official KICD source-verified curriculum. Provenance is linked through curriculum_subjects.curriculum_source_id.', (v_strand->>'order')::integer, false)
    RETURNING id INTO v_strand_id;
    v_strands := v_strands + 1;
    FOR v_sub_strand IN SELECT value FROM jsonb_array_elements(v_strand->'sub_strands') LOOP
      INSERT INTO public.curriculum_sub_strands (strand_id, sub_strand_name, sub_strand_description, sub_strand_order, is_current)
      VALUES (v_strand_id, v_sub_strand->>'sub_strand_name', 'Official KICD source-verified sub-strand; no third-tier topic record is created.', (v_sub_strand->>'order')::integer, false);
      v_sub_strands := v_sub_strands + 1;
    END LOOP;
  END LOOP;

  IF v_strands <> (v_catalog->>'strand_count')::integer OR v_sub_strands <> (v_catalog->>'sub_strand_count')::integer THEN
    RAISE EXCEPTION 'Catalog count mismatch for % Grade %: strands %/%, sub-strands %/%',
      v_catalog->>'subject',v_catalog->>'grade',v_catalog->>'strand_count',v_strands,v_catalog->>'sub_strand_count',v_sub_strands;
  END IF;
END
$stage_one_catalog$;
